# Plains bands 1700-1905: internal structure of each division (bands, villages, chiefs' followings).
# Same provenance discipline as data_src.py:
#   LISTS  - which ethnographic list supplies each division's band names, and the year it describes.
#   BANDS  - one entry per named unit. Names, glosses and list membership are documented (source in LISTS
#            or in the entry's own src); weights, activation order, tracks and merge targets are OURS unless
#            the entry's note says otherwise. Tracks are recalled from standard histories (not checked here).
#   BOBS   - band-level documented records (counts or places for a named band, village or chief's camp).
#   BSHOCK - documented attacks that fell on one band or camp; deaths are recalled ranges (not checked).
#   STRUCT - one paragraph per tribe on how the people were organized, with source.
from data_src import P, HAYDEN, DENIG, HODGE, MOONEY, CLARK

DORSEY = 'Dorsey, “Siouan Sociology” (BAE 15th Annual Report, 1897)'
H56 = HAYDEN + ', “Names of Dakota bands, with their principal chiefs”, pp. 375–76 (collected c. 1855–57)'
GRINNELL_BF = 'Grinnell, Blackfoot Lodge Tales (1892), “Social Organization”'
GRINNELL_CH = 'Grinnell, The Cheyenne Indians (1923), vol. 1, “Social Organization”'
KROEBER_A = 'Kroeber, “The Arapaho” (Bulletin AMNH 18, 1902)'
KROEBER_GV = 'Kroeber, “Ethnology of the Gros Ventre” (AMNH Anthropological Papers 1, 1908)'
LOWIE = 'Lowie, “Social Life of the Crow Indians” (AMNH Anthropological Papers 9, 1912)'
WISSLER = 'Wissler, “Social Organization and Ritualistic Ceremonies of the Blackfoot Indians” (AMNH Anthropological Papers 7, 1911)'
SWANTON = 'Swanton, The Indian Tribes of North America (BAE Bulletin 145, 1952)'
SCHOOL = 'Prescott (1850) in Schoolcraft, Historical and Statistical Information… of the Indian Tribes, vol. 3'
LC = 'Lewis & Clark journals, Oct.–Nov. 1804 (Moulton ed., UNL online edition)'
HENRY = 'Alexander Henry the younger (journal 1809–10), in Coues, New Light on the Early History of the Greater Northwest (1897), vol. 2, pp. 522–23'
REC = 'recalled from standard histories (not checked for this build)'
WP = 'Wikipedia (event dates and places checked, Oct. 2026)'

